param(
  [string]$ProductionExe = (Join-Path (Split-Path $PSScriptRoot -Parent) 'dist/thinflex-tool/ThinFlexPatch.exe'),
  [string]$TestDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/thinflex-native-test'),
  [string]$Python = 'python'
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$ProductionExe = (Resolve-Path -LiteralPath $ProductionExe).Path
New-Item -ItemType Directory -Force -Path $TestDirectory | Out-Null
$TestDirectory = (Resolve-Path -LiteralPath $TestDirectory).Path
$fixtureHeader = Join-Path $TestDirectory 'thinflex-fixture.h'
$fixtureDirectory = Join-Path $TestDirectory 'fixture'
$fixtureExe = Join-Path $fixtureDirectory 'ThinFlexPatch.exe'
if ([IO.Path]::GetFullPath($ProductionExe) -eq [IO.Path]::GetFullPath($fixtureExe)) {
  throw 'Production and fixture executables must be distinct.'
}
$testScript = Join-Path $repoRoot 'tests/test_thinflex_native.py'
& $Python $testScript --write-fixture-header $fixtureHeader
if ($LASTEXITCODE -ne 0) { throw 'Synthetic fixture identity generation failed.' }
& (Join-Path $PSScriptRoot 'build_thinflex_native.ps1') -OutputDirectory $fixtureDirectory -TestFixtureHeader $fixtureHeader
if ($LASTEXITCODE -ne 0) { throw 'Native fixture tool compilation failed.' }
if (!(Test-Path -LiteralPath $fixtureExe -PathType Leaf)) { throw 'Native fixture executable is missing.' }
# Explicit CLI execution fails for a missing executable, any failing test, or
# any skipped test. Linux discovery may skip these tests; this Windows gate may not.
& $Python $testScript --exe $fixtureExe --production-exe $ProductionExe
if ($LASTEXITCODE -ne 0) { throw 'Native ThinFlex equivalence or failure-handling tests failed.' }
Write-Host 'Native ThinFlex equivalence, production identity and failure-handling tests passed.'
